<template>
  <div class="stock-page">
    <header class="stock-header">
      <div><span class="eyebrow">INVENTORY OPERATIONS</span><h1>Stock management</h1><p>Monitor inventory levels, identify shortages and restock products quickly.</p></div>
      <div class="header-actions"><label class="search"><span>⌕</span><input v-model="query" aria-label="Search inventory" placeholder="Search products or SKU..." /></label><RouterLink to="/products/add" class="primary">+ Add product</RouterLink></div>
    </header>
    <section class="metrics">
      <article><span>Total products</span><strong>{{ products.length }}</strong><small>In your catalogue</small></article>
      <article><span>Healthy stock</span><strong class="green">{{ inStock }}</strong><small>Above reorder level</small></article>
      <article><span>Low stock</span><strong class="amber">{{ lowStock }}</strong><small>Needs attention</small></article>
      <article><span>Out of stock</span><strong class="red">{{ outOfStock }}</strong><small>Restock immediately</small></article>
    </section>
    <div v-if="message" class="notice success">{{ message }}</div><div v-if="error" class="notice error">{{ error }}</div><section class="inventory-card">
      <div class="toolbar">
        <div><h2>Inventory</h2><p>{{ filteredProducts.length }} of {{ products.length }} products</p></div>
        <div class="filters"><button v-for="filter in filters" :key="filter" :class="{active: statusFilter===filter}" @click="statusFilter=filter">{{ filter }}</button></div>
      </div>
      <div class="table-head"><span>Product</span><span>Stock</span><span>Status</span><span>Price</span><span>Action</span></div>
      <div v-for="product in filteredProducts" :key="product.product_id" class="inventory-row">
        <div class="product"><img :src="product.image" :alt="product.product_name" /><div><strong>{{ product.product_name }}</strong><span>{{ product.sku }} · {{ product.category_name || "Uncategorised" }}</span></div></div>
        <div class="quantity"><strong>{{ product.quantity }}</strong><span>units</span></div>
        <span class="badge" :class="statusClass(product.stockStatus)">{{ product.stockStatus }}</span>
        <strong class="price">{{ money(product.price) }}</strong>
        <div class="actions"><button class="edit-stock" type="button" @click="startEdit(product)">Edit</button><button class="restock" type="button" @click="restock(product)">Restock</button></div>
      </div>
      <div v-if="!filteredProducts.length" class="empty"><strong>No products found</strong><span>Try another search or filter.</span></div></section><section class="history-card"><div class="history-head"><div><h2>Recent stock activity</h2><p>Every quantity change is recorded for traceability.</p></div><button type="button" @click="loadHistory">Refresh</button></div><div v-if="historyLoading" class="history-empty">Loading stock activity...</div><div v-else-if="!history.length" class="history-empty">No stock changes have been recorded yet.</div><div v-else class="history-list"><div v-for="item in history.slice(0,8)" :key="item.stock_history_id" class="history-row"><div><strong>{{ item.product_name }}</strong><span>{{ item.reason || "Stock adjustment" }}</span></div><div><strong>{{ signedChange(item.change_quantity) }}</strong><span>{{ item.previous_quantity }} → {{ item.new_quantity }} units</span></div><time>{{ formatDate(item.created_at) }}</time></div></div></section><div v-if="editing" class="modal-backdrop" @click.self="cancelEdit"><section class="stock-modal"><button class="close" type="button" @click="cancelEdit">×</button><span class="eyebrow">STOCK ADJUSTMENT</span><h2>Update {{ editing.product_name }}</h2><p>Current stock: <strong>{{ editing.quantity }} units</strong></p><label>New quantity<input v-model.number="editQuantity" type="number" min="0" step="1" /></label><label>Reason<select v-model="editReason"><option>Manual adjustment</option><option>Delivery received</option><option>Damaged stock</option><option>Stock count correction</option><option>Returned stock</option></select></label><div class="modal-actions"><button type="button" class="cancel" @click="cancelEdit">Cancel</button><button type="button" class="save" :disabled="saving" @click="saveStock">{{ saving ? "Saving..." : "Save stock" }}</button></div></section></div>
  </div>
</template>
<script setup>
import { computed, ref } from "vue";
import { RouterLink, useRouter } from "vue-router";
import { useSupplierData } from "@/data/supplierData";
const { products, updateProductStock } = useSupplierData();
const router = useRouter(), query = ref(""), statusFilter = ref("All");
const editing = ref(null), editQuantity = ref(0), editReason = ref("Manual adjustment"), saving = ref(false), message = ref(""), error = ref("");
const history = ref([]), historyLoading = ref(false);
const filters = ["All","In stock","Low stock","Out of stock"];
const filteredProducts = computed(() => products.value.filter(p => {
  const text = `${p.product_name||""} ${p.sku||""} ${p.category_name||""}`.toLowerCase();
  const matchesSearch = text.includes(query.value.trim().toLowerCase());
  const matchesStatus = statusFilter.value === "All" || p.stockStatus?.toLowerCase() === statusFilter.value.toLowerCase();
  return matchesSearch && matchesStatus;
}));
const inStock = computed(() => products.value.filter(p => p.stockStatus === "In stock").length);
const lowStock = computed(() => products.value.filter(p => p.stockStatus === "Low stock").length);
const outOfStock = computed(() => products.value.filter(p => p.stockStatus === "Out of stock").length);
function money(value){return new Intl.NumberFormat("en-ZA",{style:"currency",currency:"ZAR",maximumFractionDigits:0}).format(Number(value)||0)}
function statusClass(status){return String(status||"").toLowerCase().replaceAll(" ","-")}
function restock(product){router.push({name:"RestockPage",params:{id:String(product.product_id)}})}
function startEdit(product){message.value="";error.value="";editing.value=product;editQuantity.value=Number(product.quantity)||0;editReason.value="Manual adjustment"}
function cancelEdit(){editing.value=null}
async function saveStock(){if(!editing.value)return;const quantity=Number(editQuantity.value);if(!Number.isInteger(quantity)||quantity<0){error.value="Quantity must be a non-negative whole number.";return}saving.value=true;error.value="";message.value="";try{await updateProductStock(editing.value.product_id,quantity,editReason.value);message.value="Stock updated successfully.";editing.value=null;await loadHistory();setTimeout(()=>{message.value=""},3500)}catch(e){error.value=e.message||"Unable to update stock."}finally{saving.value=false}}
async function loadHistory(){historyLoading.value=true;try{const token=localStorage.getItem("weconnect_token");const response=await fetch("/api/products/stock/history",{headers:token?{Authorization:`Bearer ${token}`}:{} });if(!response.ok)throw new Error("Unable to load stock history.");history.value=await response.json()}catch(e){error.value=e.message||"Unable to load stock history."}finally{historyLoading.value=false}}
function signedChange(value){const n=Number(value)||0;return `${n>0?"+":""}${n}`}
function formatDate(value){if(!value)return "—";return new Intl.DateTimeFormat("en-ZA",{dateStyle:"medium",timeStyle:"short"}).format(new Date(value))}
loadHistory();
</script>
