solute;right:15px;top:12px;border:0;background:none;font-size:25px;color:#8d7b72;cursor:pointer}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.cancel,.save{border:0;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.cancel{background:#f0ebe7;color:#66534b}.save{background:#725247;color:#fff}.save:disabled{opacity:.6;cursor:not-allowed}@media(max-width:950px){.actions{grid-column:3;grid-row:2}.history-row{grid-template-columns:1fr 130px}.history-row time{display:none}}@media(max-width:620px){.history-head{padding:17px;align-items:flex-start;gap:10px}.history-list{padding:0 17px}.history-row{grid-template-columns:1fr 90px}.history-row>div:nth-child(2){text-align:right}.actions{grid-column:1 / -1;grid-row:auto}.edit-stock,.restock{flex:1}.stock-modal{padding:23px 18px}}</style>